		{"positional arg with checkpoint flag", []string{"abc123", "--checkpoint", "def456"}},
		{"positional arg after flags", []string{"--checkpoint", "def456", "abc123"}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cmd := newExplainCmd()
