package compact

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

type CondensedEntry struct {
	Type       string
	Content    string
	ToolName   string
	ToolDetail string
}

func parseLines(content []byte) ([]transcriptLine, error) {
	trimmed := strings.TrimSpace(string(content))
	if trimmed == "" {
		return nil, nil
	}

	rawLines := strings.Split(trimmed, "\n")
	parsed := make([]transcriptLine, 0, len(rawLines))

	for _, rawLine := range rawLines {
		lineText := strings.TrimSpace(rawLine)
		if lineText == "" {
			continue
		}

		var line transcriptLine
		if err := json.Unmarshal([]byte(lineText), &line); err != nil {
			return nil, fmt.Errorf("parsing compact transcript line: %w", err)
		}
		if line.V == 0 || line.CLIVersion == "" {
			return nil, errors.New("not compact transcript format")
		}

		parsed = append(parsed, line)
	}

	return parsed, nil
}

func BuildCondensedEntries(content []byte) ([]CondensedEntry, error) {
	lines, err := parseLines(content)
	if err != nil {
		return nil, err
	}

	entries := make([]CondensedEntry, 0, len(lines))
	for _, line := range lines {
		var blocks []map[string]json.RawMessage
		if len(line.Content) > 0 {
			if err := json.Unmarshal(line.Content, &blocks); err != nil {
				continue
			}
		}

		switch line.Type {
		case "user":
			var parts []string
			for _, block := range blocks {
				var text string
				if err := json.Unmarshal(block["text"], &text); err == nil && text != "" {
					parts = append(parts, text)
				}
			}
			if len(parts) > 0 {
				entries = append(entries, CondensedEntry{Type: "user", Content: strings.Join(parts, "\n")})
			}

		case "assistant":
			for _, block := range blocks {
				var blockType string
				_ = json.Unmarshal(block["type"], &blockType)

				switch blockType {
				case "text":
					var text string
					if err := json.Unmarshal(block["text"], &text); err == nil && text != "" {
						entries = append(entries, CondensedEntry{Type: "assistant", Content: text})
					}
				case "tool_use":
					var toolName string
					_ = json.Unmarshal(block["name"], &toolName)

					var input map[string]interface{}
					if inputJSON, ok := block["input"]; ok && len(inputJSON) > 0 {
						_ = json.Unmarshal(inputJSON, &input)
					}

					entries = append(entries, CondensedEntry{
						Type:       "tool",
						ToolName:   toolName,
						ToolDetail: extractToolDetail(input),
					})
				}
			}
		}
	}

	if len(entries) == 0 {
		return nil, errors.New("no parseable compact transcript entries")
	}

	return entries, nil
}

func extractToolDetail(input map[string]interface{}) string {
	for _, key := range []string{"description", "command", "file_path", "filePath", "path", "pattern"} {
		if v, ok := input[key].(string); ok && v != "" {
			return v
		}
	}
	return ""
}

package checkpoint

import (
	"context"
	"errors"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

// CommittedReader provides read access to committed checkpoint data.
// Both GitStore (v1) and V2GitStore (v2) implement this interface.
type CommittedReader interface {
	ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
	ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
}

// ResolveCommittedReaderForCheckpoint resolves which committed checkpoint reader
// should be used for a specific checkpoint ID.
//
// Fallback behavior mirrors resume/rewind patterns:
//   - Try v2 first when preferCheckpointsV2 is true
//   - Fall back to v1 when checkpoint is not found in v2
//   - Fall back to v1 when v2 returns ErrCheckpointNotFound/ErrNoTranscript
func ResolveCommittedReaderForCheckpoint(
	ctx context.Context,
	checkpointID id.CheckpointID,
	v1Store *GitStore,
	v2Store *V2GitStore,
	preferCheckpointsV2 bool,
) (CommittedReader, *CheckpointSummary, error) {
	if err := ctx.Err(); err != nil {
		return nil, nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	if preferCheckpointsV2 && v2Store != nil {
		summary, err := v2Store.ReadCommitted(ctx, checkpointID)
		if err == nil && summary != nil {
			return v2Store, summary, nil
		}
		if err != nil && !errors.Is(err, ErrCheckpointNotFound) && !errors.Is(err, ErrNoTranscript) {
			return nil, nil, err
		}
	}

	if v1Store == nil {
		return nil, nil, ErrCheckpointNotFound
	}

	summary, err := v1Store.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return nil, nil, err
	}
	if summary == nil {
		return nil, nil, ErrCheckpointNotFound
	}

	return v1Store, summary, nil
}

// ResolveRawSessionLogForCheckpoint resolves the raw transcript log bytes for a
// checkpoint with v2-first, v1-fallback behavior.
//
// Fallback behavior mirrors resume/rewind patterns:
//   - Try v2 first when preferCheckpointsV2 is true
//   - Fall back to v1 when checkpoint/transcript is missing in v2
func ResolveRawSessionLogForCheckpoint(
	ctx context.Context,
	checkpointID id.CheckpointID,
	v1Store *GitStore,
	v2Store *V2GitStore,
	preferCheckpointsV2 bool,
) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err //nolint:wrapcheck // Propagating context cancellation
	}

	if preferCheckpointsV2 && v2Store != nil {
		content, sessionID, err := v2Store.GetSessionLog(ctx, checkpointID)
		if err == nil && len(content) > 0 {
			return content, sessionID, nil
		}
		if err != nil && !errors.Is(err, ErrCheckpointNotFound) && !errors.Is(err, ErrNoTranscript) {
			return nil, "", err
		}
	}

	if v1Store == nil {
		return nil, "", ErrCheckpointNotFound
	}

	return v1Store.GetSessionLog(ctx, checkpointID)
}

