		SessionID:  "session-2",
		BaseCommit: "abc1234",
		StartedAt:  time.Now(),
		StepCount:  2,
	}
	state3 := &SessionState{
		SessionID:  "session-3",
		BaseCommit: "xyz7890",
		StartedAt:  time.Now(),
		StepCount:  3,
	}

	for _, state := range []*SessionState{state1, state2, state3} {
